#!/bin/sh
# Build and sign this launcher. Generated by `ctx make launcher`; kept next to the binary so you
# can read exactly what you're granting.
set -eu
cd "$(dirname "$0")"
/usr/bin/clang -O2 -Wall -Wextra -o "@NAME@" launcher.c -framework Security -framework CoreFoundation
/usr/bin/codesign --force @SIGN_FLAGS@ --identifier "@IDENTIFIER@" "@NAME@"
